use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        // Exactly one permitted fetch. A transport failure is a value (fetched = 0);
        // an out-of-allowlist URL traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat t={} fetched={}", now.seconds, fetched);

        // The contract requires notified == true on every produced output.
        // If the notifier refuses every attempt, no report is produced at all
        // (a trap), rather than a report claiming notified = false.
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused all attempts; no heartbeat report produced");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
